import urllib.request, ssl; ctx = ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE; req = urllib.request.Request('https://m.flashscore.com.tr/?s=1', headers={'User-Agent': 'Mozilla/5.0'}); html = urllib.request.urlopen(req, context=ctx).read().decode('utf-8'); print(html[:500])
